        // [WSCoop] Luminary respec: "reset" takes back the whole menu (after a confirmation), "undo" the selected one.
        UWSLuminaryRespecSubsystem Respec = WSLuminaryRespec::Tracker();
        if (Respec != nullptr && Respec.RegisterPanel(this))
        {
            UInputAction ResetAction = WSLuminaryRespec::LoadAction(WSLuminaryRespec::ResetActionPath);
