            if (ResetAction != nullptr)
                RegisterUIActionBinding(ResetAction, FSimpleDynamicDelegate(this, n"WSOnResetPressed"));
            if (UndoAction != nullptr)
                RegisterUIActionBinding(UndoAction, FSimpleDynamicDelegate(this, n"WSOnUndoPressed"));
        }
    }

